import json
from pathlib import Path
from fastapi import APIRouter
from backend.routes.staff import DEFAULT_STAFF

router = APIRouter()

# shared/playbook.json is the single source of truth for both the frontend
# (fetched directly) and this backend (loaded here) so play ids/names/roles
# always match. server/routes/ -> repo root is two levels up.
current_file = Path(__file__).resolve()
project_root = current_file.parents[2] if len(current_file.parents) > 2 else current_file.parent
PLAYBOOK_FILE_PATH = project_root / "shared" / "playbook.json"


def load_playbook():
    try:
        with open(PLAYBOOK_FILE_PATH, "r", encoding="utf-8") as f:
            catalog = json.load(f)
        # Keep the existing list-based lookup contract used by game_stream.py
        return list(catalog.values())
    except FileNotFoundError:
        print(f"[ERROR] Playbook catalog not found at {PLAYBOOK_FILE_PATH}")
        return []


PLAY_DATABASE = load_playbook()

