def _get_idea_team(team_code: str):
    idea_dir = project_root / "idea"
    target_path = idea_dir / f"{team_code.lower()}.json"
    if not target_path.exists():
        target_path = idea_dir / "saints.json"
    if target_path.exists():
        try:
            with open(target_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            pass
    return {}


@router.get("/evaluate-matchup")
async def evaluate_matchup(play_id: str = "ari_38", offense_team: str = "STEELERS", defense_team: str = "SAINTS"):
    """
    Calculates dynamic route distance, matchup OVR delta, success probability %,
    and visual mismatch highlights for a given play and team matchup.
    """
    off_data = _get_idea_team(offense_team)
    def_data = _get_idea_team(defense_team)

    qb = off_data.get("QB", {"name": "Quarterback", "short": 70, "medium": 70, "long": 70, "pa": 70, "run": 50})
    receivers = off_data.get("Receivers", [])
    
    play = next((p for p in PLAY_DATABASE if str(p.get("id")) == str(play_id) or str(p.get("num_id")) == str(play_id)), PLAY_DATABASE[0])

    evaluations = []
    routes = play.get("routes", [])

    for r in routes:
        role = r.get("player")
        if role in ["QB", "FB", "BSG", "BST", "OL"]:
            continue
        
        waypoints = r.get("waypoints", [])
        if not waypoints:
            continue

        # 1. Route Distance Calculation
        start_wp = waypoints[0]
        end_wp = waypoints[-1]
        depth = abs(end_wp[1] - start_wp[1])

        if depth < 12.0:
            dist_cat = "Short"
            qb_acc = qb.get("short", 70)
        elif depth <= 22.0:
            dist_cat = "Medium"
            qb_acc = qb.get("medium", 70)
        else:
            dist_cat = "Long"
            qb_acc = qb.get("long", 70)

        # 2. Matchup Receiver OVR vs Coverage DB OVR
        rec_info = next((rec for rec in receivers if rec.get("position") in (role, "WR1" if role == "X" else ("WR2" if role == "Z" else ("SLOT" if role == "Y" else role)))), {"name": role, "ovr": 80})
        rec_ovr = rec_info.get("ovr", 80)
        def_ovr = 80  # Baseline coverage defender
        delta = rec_ovr - def_ovr

        # Chief Scout & Data Analyst Staff Boosts
        scout = DEFAULT_STAFF.get("CHIEF_SCOUT", {})
        scout_rating = scout.get("scouting_rating", 90)
        analyst = DEFAULT_STAFF.get("DATA_ANALYST", {})
        analytics_rating = analyst.get("analytics_rating", 94)

        scout_bonus = (scout_rating - 75) * 0.35
        analyst_bonus = (analytics_rating - 75) * 0.25
        success_pct = int(min(98, max(20, (qb_acc * 0.45) + (delta * 1.2) + 20 + scout_bonus + analyst_bonus)))

        if success_pct >= 75:
            rating_label = "High Advantage"
            highlight_color = "#4ade80"  # Bright Green
        elif success_pct >= 58:
            rating_label = "Moderate"
            highlight_color = "#fde68a"  # Light Yellow / Green
        else:
            rating_label = "Low / Contested"
            highlight_color = "#f87171"  # Red

        evaluations.append({
            "player": role,
            "target_name": rec_info.get("name", role),
            "receiver_ovr": rec_ovr,
            "distance_category": dist_cat,
            "route_depth_yards": round(depth, 1),
            "qb_accuracy_used": qb_acc,
            "matchup_delta": delta,
            "success_probability_pct": success_pct,
            "success_rating": rating_label,
            "highlight_color": highlight_color
        })

    primary_mismatch = max(evaluations, key=lambda x: x["success_probability_pct"]) if evaluations else None
    scout_name = DEFAULT_STAFF.get("CHIEF_SCOUT", {}).get("name", "Chief Scout")
    scout_rating = DEFAULT_STAFF.get("CHIEF_SCOUT", {}).get("scouting_rating", 91)

    return {
        "play_id": play_id,
        "play_name": play.get("name", play.get("play_name")),
        "offense_team": off_data.get("Team", {}).get("name", offense_team),
        "qb_name": qb.get("name"),
        "chief_scout_intel": f"{scout_name} (Scout {scout_rating}): Evaluated against {defense_team} defense.",
        "evaluations": evaluations,
        "primary_mismatch": primary_mismatch
    }


@router.get("/recommendations/{team_code}")
async def get_team_playbook_recommendations(team_code: str):
    """
    Auto-generates recommended scheme profile and recommended plays based on team JSON stats.
    """
    team_data = _get_idea_team(team_code)
    team_name = team_data.get("Team", {}).get("name", team_code.upper())
    qb = team_data.get("QB", {})

    is_star_driven = qb.get("long", 70) > qb.get("short", 70) or any(rec.get("ovr", 0) >= 95 for rec in team_data.get("Receivers", []))

    if is_star_driven:
        scheme_profile = "Star-Driven / Deep Shots & Iso Workhorse"
        recommended_categories = ["Deep Shots", "WR1 Isolations", "RB Stretch Runs"]
        recommended_play_ids = ["ari_28", "ari_38", "ari_40", "ari_14"]
    else:
        scheme_profile = "Balanced Rhythm / West Coast Progression Spread"
        recommended_categories = ["West Coast Quick Passes", "RPO Slants", "TE Seam Routes"]
        recommended_play_ids = ["ari_33", "ari_29", "ari_37", "ari_41"]

    recommended_plays = [p for p in PLAY_DATABASE if p.get("id") in recommended_play_ids or p.get("key") in recommended_play_ids]

    return {
        "team_name": team_name,
        "scheme_profile": scheme_profile,
        "recommended_categories": recommended_categories,
        "recommended_plays": recommended_plays if recommended_plays else PLAY_DATABASE[:4]
    }

